INSERT INTO auth.users(id,aud,role,email,email_confirmed_at) VALUES('a1570000-0000-0000-0000-000000000001','authenticated','authenticated','qa-month-owner@example.test',now());
INSERT INTO monthly_vars SELECT 'ws',id FROM public.workspaces WHERE owner_id='a1570000-0000-0000-0000-000000000001';
INSERT INTO monthly_vars SELECT 'member',id FROM public.workspace_members WHERE workspace_id=(SELECT id FROM monthly_vars WHERE name='ws');
INSERT INTO monthly_vars SELECT 'pur',public.fn_create_purchase_with_splits(p_workspace_id=>(SELECT id FROM monthly_vars WHERE name='ws'),p_description=>'Monthly 600/3',p_total_amount=>600,p_installment_count=>3,p_purchase_date=>'2050-09-10',p_paid_by_member_id=>(SELECT id FROM monthly_vars WHERE name='member'),p_split_type=>'equal',p_splits=>jsonb_build_array(jsonb_build_object('member_id',(SELECT id FROM monthly_vars WHERE name='member'),'amount',300),jsonb_build_object('person_id',(SELECT id FROM monthly_vars WHERE name='person'),'amount',300)));
INSERT INTO monthly_vars SELECT 'pur2',public.fn_create_purchase_with_splits(p_workspace_id=>(SELECT id FROM monthly_vars WHERE name='ws'),p_description=>'Second 600/3',p_total_amount=>600,p_installment_count=>3,p_purchase_date=>'2050-09-10',p_paid_by_member_id=>(SELECT id FROM monthly_vars WHERE name='member'),p_split_type=>'equal',p_splits=>jsonb_build_array(jsonb_build_object('member_id',(SELECT id FROM monthly_vars WHERE name='member'),'amount',300),jsonb_build_object('person_id',(SELECT id FROM monthly_vars WHERE name='person'),'amount',300)));
INSERT INTO monthly_results SELECT lives_ok($q$SELECT public.fn_mark_monthly_repayments((SELECT id FROM monthly_vars WHERE name='ws'),'2050-10',(SELECT id FROM monthly_vars WHERE name='person'),(SELECT plan FROM monthly_plan))$q$,'Monthly batch succeeds');
INSERT INTO monthly_results SELECT is((SELECT min(repaid_installments_count) FROM public.purchase_splits WHERE person_id=(SELECT id FROM monthly_vars WHERE name='person')),2,'Both purchases marked through October');
INSERT INTO monthly_results SELECT is((SELECT sum(repaid_amount) FROM public.purchase_splits WHERE person_id=(SELECT id FROM monthly_vars WHERE name='person')),400::numeric,'Exact two-month shares recognized');
INSERT INTO monthly_results SELECT ok(NOT EXISTS(SELECT 1 FROM public.installments i JOIN monthly_original old ON i.id=old.id WHERE i IS DISTINCT FROM old),'Installment bank payment history untouched');
INSERT INTO monthly_results SELECT is((SELECT count(*)::int FROM public.payments WHERE workspace_id=(SELECT id FROM monthly_vars WHERE name='ws')),0,'No bank payment created');
INSERT INTO monthly_results SELECT is((SELECT count(*)::int FROM public.settlements WHERE workspace_id=(SELECT id FROM monthly_vars WHERE name='ws')),0,'No duplicate manual settlement created');
INSERT INTO monthly_results SELECT throws_ok($q$SELECT public.fn_mark_monthly_repayments((SELECT id FROM monthly_vars WHERE name='ws'),'2050-10',(SELECT id FROM monthly_vars WHERE name='person'),(SELECT plan FROM monthly_plan))$q$,'PT409',NULL,'Stale batch rejected');
INSERT INTO monthly_results SELECT lives_ok($q$SELECT public.fn_mark_monthly_repayments((SELECT id FROM monthly_vars WHERE name='ws'),'2050-10',(SELECT id FROM monthly_vars WHERE name='person'),'[]')$q$,'Already complete batch is no-op');
INSERT INTO monthly_plan SELECT public.fn_monthly_repayment_plan((SELECT id FROM monthly_vars WHERE name='ws'),'2050-11',(SELECT id FROM monthly_vars WHERE name='person'));
INSERT INTO monthly_results SELECT throws_ok($q$SELECT public.fn_mark_monthly_repayments((SELECT id FROM monthly_vars WHERE name='ws'),'2050-11',(SELECT id FROM monthly_vars WHERE name='person'),(SELECT plan FROM monthly_plan))$q$,NULL,NULL,'One invalid purchase aborts the full batch');
INSERT INTO monthly_results SELECT is((SELECT max(repaid_installments_count) FROM public.purchase_splits WHERE person_id=(SELECT id FROM monthly_vars WHERE name='person')),2,'Earlier updates in failing batch rolled back');
INSERT INTO monthly_results SELECT throws_ok($q$SELECT public.fn_mark_monthly_repayments((SELECT id FROM monthly_vars WHERE name='ws'),'invalid',(SELECT id FROM monthly_vars WHERE name='person'),'[]')$q$,'23514',NULL,'Invalid month rejected');
INSERT INTO monthly_results SELECT throws_ok($q$SELECT public.fn_mark_monthly_repayments('00000000-0000-0000-0000-000000000000','2050-10',(SELECT id FROM monthly_vars WHERE name='person'),'[]')$q$,'42501',NULL,'Foreign workspace denied');
INSERT INTO monthly_results SELECT throws_ok($q$SELECT public.fn_mark_monthly_repayments((SELECT id FROM monthly_vars WHERE name='ws'),'2050-10','00000000-0000-0000-0000-000000000000','[]')$q$,'23514',NULL,'Foreign participant denied');
INSERT INTO monthly_results SELECT throws_ok($q$SELECT public.fn_mark_monthly_repayments((SELECT id FROM monthly_vars WHERE name='ws'),'2050-10',(SELECT id FROM monthly_vars WHERE name='person'),'[]')$q$,'42501',NULL,'Viewer cannot mark repayments');
INSERT INTO monthly_results SELECT ok(NOT has_function_privilege('anon','public.fn_mark_monthly_repayments(uuid,text,uuid,jsonb)','EXECUTE'),'Anonymous batch denied');
INSERT INTO monthly_results SELECT ok(NOT has_function_privilege('authenticated','public.fn_monthly_repayment_plan(uuid,text,uuid)','EXECUTE'),'Internal preview helper is private');
