BEGIN;
SELECT plan(16);
CREATE TEMP TABLE monthly_results(msg text);
CREATE TEMP TABLE monthly_vars(name text,id uuid);
UPDATE public.workspaces SET tracking_mode='expense_tracker' WHERE id=(SELECT id FROM monthly_vars WHERE name='ws');
WITH p AS(INSERT INTO public.people(workspace_id,name) SELECT id,'Monthly Person' FROM monthly_vars WHERE name='ws' RETURNING id) INSERT INTO monthly_vars SELECT 'person',id FROM p;
SELECT set_config('request.jwt.claim.sub','a1570000-0000-0000-0000-000000000001',true);
CREATE TEMP TABLE monthly_plan AS SELECT public.fn_monthly_repayment_plan((SELECT id FROM monthly_vars WHERE name='ws'),'2050-10',(SELECT id FROM monthly_vars WHERE name='person')) AS plan;
CREATE TEMP TABLE monthly_original AS SELECT * FROM public.installments WHERE purchase_id IN(SELECT id FROM monthly_vars WHERE name IN('pur','pur2'));
GRANT ALL ON monthly_vars,monthly_plan,monthly_original,monthly_results TO authenticated;
SET LOCAL role='authenticated';
RESET ROLE;
TRUNCATE monthly_plan;
UPDATE public.installments SET status='cancelled' WHERE purchase_id=(SELECT max(id::text)::uuid FROM monthly_vars WHERE name IN('pur','pur2')) AND installment_number=3;
SET LOCAL role='authenticated';
RESET ROLE;
UPDATE public.workspace_members SET role='viewer' WHERE id=(SELECT id FROM monthly_vars WHERE name='member');
SET LOCAL role='authenticated';
RESET ROLE;
SELECT (SELECT array_agg(msg) FROM monthly_results WHERE msg LIKE 'not ok%') AS not_ok_messages,extensions._get('curr_test')::int AS ran,extensions._get('plan')::int AS planned,extensions.num_failed()::int AS failed,ARRAY(SELECT * FROM extensions.finish()) AS finish_diagnostics;
ROLLBACK;
